n = int(input())
parent = {}
children = {}
for _ in range(n - 1):
    child, ancestor = input().split()
    parent[child] = ancestor
    children.setdefault(ancestor, []).append(child)
    children.setdefault(child, [])

root = next(name for name in children if name not in parent)
order = [root]
for name in order:
    order.extend(children[name])
count = {name: 0 for name in children}
for name in reversed(order):
    if name in parent:
        count[parent[name]] += count[name] + 1
for name in sorted(count):
    print(name, count[name])

